// Extract Ghost Rider leads from Convex response
var response = $input.first().json;
var leads = response.leads || [];

if (leads.length === 0) {
  return [{ json: { noLeads: true, message: 'No Ghost Rider leads ready for CRM' } }];
}

function titleCase(s) {
  if (!s) return '';
  return s.split(' ').map(function(word) {
    if (!word) return '';
    // Keep numbers and short words like 'AVE', 'ST' properly cased
    if (/^\d/.test(word)) return word; // starts with number, keep as-is
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  }).join(' ');
}

console.log('Found ' + leads.length + ' Ghost Rider leads to process');

return leads.map(function(lead) {
  return {
    json: {
      _id: lead.parcelId,
      parcelId: lead.parcelId,
      firstName: titleCase(lead.firstName),
      lastName: titleCase(lead.lastName),
      phone: lead.phone,
      address: titleCase(lead.street),
      city: titleCase(lead.city || 'Cleveland'),
      state: lead.state || 'OH',
      zip: lead.zip || '',
      county: 'Cuyahoga',
      distressScore: lead.distressScore || 0,
      primaryDistress: (lead.primaryDistress || '').toLowerCase().replace(/\s+/g, '_'),
      listingType: 'BRRRR',
      tier: 'Ghost Rider',
      tierName: 'Ghost Rider',
      action: lead.action || 'call',
      email: null
    }
  };
});

return [{
  json: {
    status: 'no_leads',
    message: 'No pending leads in Convex staging',
    processed: 0
  }
}];

const allItems = $input.all().map(item => item.json);

const stats = {
  date: new Date().toISOString().split('T')[0],
  processed: 0,
  skippedDnc: 0,
  failed: 0,
  noLeads: false
};

for (const item of allItems) {
  if (item.noLeads) {
    stats.noLeads = true;
  } else if (item.status === 'skipped_dnc') {
    stats.skippedDnc++;
  } else if (item.status === 'failed') {
    stats.failed++;
  } else if (item.success || item.smsSent) {
    stats.processed++;
  }
}

stats.total = stats.processed + stats.skippedDnc + stats.failed;
stats.successRate = stats.total > 0 ? ((stats.processed / stats.total) * 100).toFixed(1) + '%' : '0%';

return [{ json: stats }];

// Ghost Rider - Fixed phone, Thompson Sampling templates
var CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';
var lead = $('Has Leads?').item.json;
var closeResponse = $('Create Close CRM Lead').item.json;
var assigned_phone_number = { phone: '+15555550100' };
var phone_source = 'ghost_rider_fixed';
var DISTRESS_MAP = {'pre_foreclosure':'Preforeclosure','preforeclosure':'Preforeclosure','probate':'Probate','inherited':'Probate','vacant':'Vacant','tax_delinquent':'Tax_Delinquent','tax_default':'Tax_Delinquent','lien':'Tax_Delinquent','absentee_owner':'Absentee','absentee':'Absentee','out_of_state':'Absentee','tired_landlord':'Absentee','high_equity':'High_Equity','senior_owner':'High_Equity','code_violation':'Code_Violation','code_violations':'Code_Violation'};
var listingType = 'BRRRR';
var distressType = null;
var distressSource = 'none';
if (lead.primaryDistress && DISTRESS_MAP[lead.primaryDistress.toLowerCase()]) {
  distressType = DISTRESS_MAP[lead.primaryDistress.toLowerCase()];
  distressSource = 'primaryDistress';
}
var template1_id = null;
var template1_variant = 'fallback';
var template1_source = 'fallback';
var templateBody = null;
var fallbackTemplates = ['Hey, got your message about {street_name}. What did you mean?','Hey, someone gave me this number for {street_name}. That you?','Hey, {street_name} - call me back when you get this','Hey, {street_name} came up. You still have it?'];
try {
  var apiUrl = CONVEX_URL + '/api/template-select-thompson?position=1&listing_type=' + encodeURIComponent(listingType);
  if (distressType) apiUrl += '&distress_type=' + encodeURIComponent(distressType);
  var templateResp = await this.helpers.httpRequest({ method: 'GET', url: apiUrl, returnFullResponse: false });
  if (templateResp && templateResp.selected && templateResp.selected.body) {
    templateBody = templateResp.selected.body;
    template1_id = templateResp.selected._id;
    template1_variant = templateResp.selected.variant_name || 'thompson';
    template1_source = 'thompson_sampling';
  } else { throw new Error('No template returned'); }
} catch (e) {
  templateBody = fallbackTemplates[Math.floor(Math.random() * fallbackTemplates.length)];
  template1_id = 'fallback_curiosity';
}
var address = lead.address || 'your property';
var streetName = address.replace(/^\d+\s+/, '').split(',')[0].trim();
var sms_text = templateBody.replace(/\{street_name\}/gi, streetName).replace(/\{street\}/gi, streetName).replace(/\{address\}/gi, address).replace(/\{city\}/gi, lead.city || '').replace(/\{firstName\}/gi, lead.firstName || '').replace(/\{first_name\}/gi, lead.firstName || '').replace(/\{\{street_name\}\}/gi, streetName).replace(/\{\{street\}\}/gi, streetName).replace(/\{\{address\}\}/gi, address);
var now = new Date();
var tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);
tomorrow.setHours(9, 0, 0, 0);
return [{json: {_id: lead._id, parcelId: lead.parcelId, stagedLeadId: lead._id, tier: lead.tier, tierName: lead.tierName, listingType: listingType, distressType: distressType, distressSource: distressSource, primaryDistress: lead.primaryDistress || 'none', closeLeadId: closeResponse.id, contactId: closeResponse.contacts && closeResponse.contacts[0] ? closeResponse.contacts[0].id : null, firstName: lead.firstName, lastName: lead.lastName, phone: lead.phone, address: lead.address, city: lead.city, state: lead.state || 'OH', zip: lead.zip, assigned_phone_number: assigned_phone_number, phone_source: phone_source, template1_id: template1_id, template1_variant: template1_variant, template1_source: template1_source, sms_text: sms_text, text1_sent: now.toISOString(), text2_scheduled: tomorrow.toISOString()}}];

// Log SMS to Convex - Ghost Rider (no phone pool rotation)
var CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';
var selectData = $('Select Phone & Template').item.json;
var smsResponse = $('Send Text 1').item.json;
try {
  await this.helpers.httpRequest({method: 'POST', url: CONVEX_URL + '/api/conversation-log', body: {lead_id: selectData.closeLeadId, phone: selectData.phone, direction: 'outbound', message_text: selectData.sms_text, template_id: selectData.template1_id || null, close_activity_id: smsResponse.id || null}, json: true, returnFullResponse: false});
} catch (e) { console.log('Failed to log SMS:', e.message); }
return [{json: {success: true, closeLeadId: selectData.closeLeadId, stagedLeadId: selectData.stagedLeadId, parcelId: selectData.parcelId, tier: selectData.tier, phone: selectData.phone, firstName: selectData.firstName, address: selectData.address, city: selectData.city, zip: selectData.zip, listingType: selectData.listingType, assigned_phone_number: selectData.assigned_phone_number, template1_id: selectData.template1_id, template1_variant: selectData.template1_variant, template1_source: selectData.template1_source, text2_scheduled: selectData.text2_scheduled, smsSent: true}}];

const input = $input.first().json;
const now = new Date();
const estString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });
const estDate = new Date(estString);
const currentHourEST = estDate.getHours();
const dayOfWeekEST = estDate.getDay();

let canSend = true;
let skipReason = '';

if (dayOfWeekEST === 0) {
  canSend = false;
  skipReason = 'Sunday - no SMS allowed';
} else if (dayOfWeekEST === 6) {
  if (currentHourEST < 10 || currentHourEST >= 18) {
    canSend = false;
    skipReason = 'Saturday outside 10AM-6PM EST';
  }
} else {
  if (currentHourEST < 9 || currentHourEST >= 20) {
    canSend = false;
    skipReason = 'Outside 9AM-8PM EST window';
  }
}

return [{
  json: {
    ...input,
    tcpaCheck: { canSend, skipReason, checkedAt: now.toISOString(), currentHourEST, dayOfWeekEST }
  }
}];

const input = $('TCPA Time Check').item.json;

return [{
  json: {
    success: true,
    closeLeadId: input.closeLeadId,
    stagedLeadId: input.stagedLeadId,
    tier: input.tier,
    smsSent: false,
    tcpaDeferred: true,
    reason: input.tcpaCheck?.skipReason || 'Outside TCPA window'
  }
}];

// PREPARE LEAD DATA - Tier lookup + null handling for Close CRM
var CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';
var lead = $('Has Leads?').item.json;

// Get current tier info
var tier = lead.tier || '';
var tierName = lead.tierName || '';
var listingType = lead.listingType || '';

// If tier is empty and we have a ZIP, try to lookup from tier_configs
if (!tier && lead.zip) {
  try {
    var tierResp = await this.helpers.httpRequest({
      method: 'GET',
      url: CONVEX_URL + '/api/tier-configs/by-zip?zip=' + encodeURIComponent(lead.zip),
      returnFullResponse: false
    });

    if (tierResp && tierResp.tier) {
      tier = tierResp.tier;
      tierName = tierResp.name || tierResp.tierName || tier;
      listingType = tierResp.listing_type || tierResp.listingType || 'BRRRR';
      console.log('Tier lookup success: ' + tier + ' (' + tierName + ') for ZIP ' + lead.zip);
    }
  } catch (e) {
    console.log('Tier lookup failed:', e.message);
  }
}

// Default tier if still empty
if (!tier) {
  tier = 'General';
  tierName = 'General Leads';
  listingType = 'BRRRR';
  console.log('Using default tier: General');
}

// Default listing type
if (!listingType) {
  listingType = 'BRRRR';
}

// Helper to convert empty strings to null for Close CRM
var nullIfEmpty = function(val) { return (val && val.trim && val.trim() !== '') ? val : null; };

// Normalize distress type for Close CRM
var DISTRESS_NORMALIZE = {
  'code_violations': 'code_violation',
  'code_violation': 'code_violation',
  'tax_delinquent': 'tax_delinquent',
  'tax_default': 'tax_delinquent',
  'vacant': 'vacant',
  'pre_foreclosure': 'pre_foreclosure',
  'preforeclosure': 'pre_foreclosure',
  'probate': 'probate',
  'inherited': 'probate',
  'absentee_owner': 'absentee_owner',
  'absentee': 'absentee_owner',
  'out_of_state': 'out_of_state',
  'tired_landlord': 'absentee_owner',
  'lien': 'lien',
  'high_equity': 'high_equity',
  'senior_owner': 'senior_owner'
};
var rawDistress = (lead.primaryDistress || '').toLowerCase().replace(/\s+/g, '_');
var normalizedDistress = DISTRESS_NORMALIZE[rawDistress] || rawDistress || null;
// Only null out if truly empty
if (normalizedDistress === '') normalizedDistress = null;

// Prepare the lead data with null handling
return [{
  json: {
    // Original lead data
    ...lead,
    // Override with resolved tier info
    tier: tier,
    tierName: tierName,
    listingType: listingType,
    // Prepared Close CRM fields (null if empty)
    _closeCRM: {
      name: ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || 'Unknown',
      address: nullIfEmpty(lead.address),
      city: nullIfEmpty(lead.city),
      state: lead.state || 'OH',
      county: nullIfEmpty(lead.county) || 'Cuyahoga',
      tierName: nullIfEmpty(tierName),
      listingType: listingType === 'HIGH_ARV' || listingType === 'High_ARV' ? 'ARV' : 'BRRRR',
      primaryDistress: normalizedDistress,
      distressScore: lead.distressScore || 0
    }
  }
}];
